package com.garagedesk.controller; import com.garagedesk.entity.Vehicle; import com.garagedesk.service.VehicleService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/vehicles") public class VehicleController{final VehicleService s;public VehicleController(VehicleService s){this.s=s;}@GetMapping public List<Vehicle> all(){return s.all();}@GetMapping("/{id}")public Vehicle get(@PathVariable Long id){return s.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Vehicle create(@Valid @RequestBody Vehicle v){return s.create(v);}@PutMapping("/{id}")public Vehicle update(@PathVariable Long id,@Valid @RequestBody Vehicle v){return s.update(id,v);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){s.delete(id);}}
